//! Static table of the standard Unicode emoji set for the picker, grouped in
//! Discord's category order. Each entry has its glyph, a `:name:` slug and a few
//! search keywords. GENERATED from Unicode's emoji-test.txt (official groups,
//! fully-qualified only, default skin tone); do not edit by hand. 1923 emoji.
//! `Recent` is not stored here: the picker synthesizes it from local picks.

/// One emoji: its glyph, a `:name:` slug, and search keywords.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Emoji {
    pub glyph: &'static str,
    pub name: &'static str,
    pub keywords: &'static [&'static str],
}

/// A picker category: its tab label and its emoji, in Unicode order.
#[derive(Debug)]
pub struct Category {
    pub label: &'static str,
    pub emojis: &'static [Emoji],
}

const fn e(glyph: &'static str, name: &'static str, keywords: &'static [&'static str]) -> Emoji {
    Emoji { glyph, name, keywords }
}

