/// Every emoji, in tab order.
pub fn all_emojis() -> impl Iterator<Item = &'static Emoji> {
    CATEGORIES.iter().flat_map(|c| c.emojis.iter())
}

/// Whether `e` matches the search text `q` (case-insensitive substring of its
/// name or any keyword). An empty query matches everything.
pub fn matches(q: &str, e: &Emoji) -> bool {
    let q = q.trim().trim_matches(':').to_lowercase();
    q.is_empty() || e.name.contains(q.as_str()) || e.keywords.iter().any(|k| k.contains(q.as_str()))
}

/// Looks an emoji up by glyph (e.g. for the hover footer of a recent pick).
pub fn find(glyph: &str) -> Option<&'static Emoji> {
    all_emojis().find(|e| e.glyph == glyph)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_complete_and_unique() {
        let all: Vec<_> = all_emojis().collect();
        assert!(all.len() > 1500, "only {} emoji", all.len());
        let mut glyphs: Vec<_> = all.iter().map(|e| e.glyph).collect();
        glyphs.sort_unstable();
        glyphs.dedup();
        assert_eq!(glyphs.len(), all.len(), "duplicate glyphs");
        let mut names: Vec<_> = all.iter().map(|e| e.name).collect();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), all.len(), "duplicate names");
        for g in ["\u{1F44C}", "\u{1F446}", "\u{1F384}", "\u{1F948}", "\u{1F600}"] {
            assert!(find(g).is_some(), "missing {g}");
        }
    }

    #[test]
    fn search_matches_names_and_keywords() {
        let thumbs = find("\u{1F44D}").unwrap();
        assert!(matches("thumbs", thumbs));
        assert!(matches(":+1", thumbs) || matches("thumbsup", thumbs));
        assert!(matches("", thumbs));
        assert!(!matches("zebra", thumbs));
    }
}
